$ErrorActionPreference='Stop'; $root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path; $task=Join-Path $root 'examples/tasks/bugfix.json'; $out=& powershell -NoProfile -File (Join-Path $root 'bin/new-runtime-session.ps1') -TaskPath $task | ConvertFrom-Json; foreach($k in @('taskId','objective','lane','capabilities','budgets','policy','provider','stopReasons')){if($null -eq $out.$k){throw "contract-missing:$k"}}; if($out.budgets.maxIterations -lt 1 -or $out.policy.allowedMcpServers.Count -ne 0){throw 'contract-defaults-invalid'}; 'RUNTIME_CONTRACT_TESTS_OK'
